const f = Object.fromEntries(Object.entries($json).map(([k, v]) => [k.trim(), v]));
const get = (k) => (f[k] ?? '').toString().trim();
const cnpj = get('CNPJ').replace(/\D/g, '');
function cnpjValido(c) {
  if (!/^\d{14}$/.test(c) || /^(\d)\1{13}$/.test(c)) return false;
  const calc = (base, pesos) => {
    const s = base.split('').reduce((a, d, i) => a + Number(d) * pesos[i], 0);
    const r = s % 11;
    return r < 2 ? 0 : 11 - r;
  };
  const p1 = [5,4,3,2,9,8,7,6,5,4,3,2];
  const p2 = [6, ...p1];
  const d1 = calc(c.slice(0, 12), p1);
  const d2 = calc(c.slice(0, 12) + d1, p2);
  return c.endsWith(`${d1}${d2}`);
}
const pendencias = [];
for (const k of ['CNPJ','Razão social','Nome fantasia','E-mail','Telefone','Cidade/UF','Cardápio']) {
  if (!get(k)) pendencias.push(`Campo não preenchido: ${k}`);
}
const cnpjOk = cnpjValido(cnpj);
if (!cnpjOk) pendencias.push('CNPJ inválido: confira os números digitados');
const tel = get('Telefone');
if (tel && !/^\(?\d{2}\)?\s?9?\d{4}-?\d{4}$/.test(tel)) {
  pendencias.push('Telefone inválido: use o formato (21) 99999-9999');
}
const fmt = cnpj.length === 14
  ? `${cnpj.slice(0,2)}.${cnpj.slice(2,5)}.${cnpj.slice(5,8)}/${cnpj.slice(8,12)}-${cnpj.slice(12)}`
  : get('CNPJ');
return { json: {
  cnpj, cnpj_formatado: fmt, cnpj_valido: cnpjOk,
  razao_social: get('Razão social'), nome_fantasia: get('Nome fantasia'),
  email: get('E-mail'), telefone: tel, cidade_uf: get('Cidade/UF'),
  cardapio: get('Cardápio').replace(/^"+|"+$/g, '').trim(), pendencias_regras: pendencias, envio_id: 'envio-' + (f['Carimbo de data/hora'] || f['submittedAt'] || '')
}};

const r = $('Regras de cadastro').item.json;
const simulada = $('Consultar Receita').item.json;
const api = $json;
const norm = s => (s || '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
// Razão social sem pontuação e sem sufixos societários (LTDA, ME, EPP, EIRELI, S/A)
const normRazao = s => norm(s).replace(/[^a-z0-9 ]/g, ' ').replace(/\b(ltda|me|epp|eireli|s a|sa)\b/g, ' ').replace(/\s+/g, ' ').trim();

// 1. Receita em duas camadas: base simulada (testes) e, se o CNPJ não estiver nela, BrasilAPI (CNPJs reais)
let receita = null;
if (simulada['Situação cadastral']) {
  receita = { situacao: simulada['Situação cadastral'], cnae: String(simulada['CNAE principal'] || ''), descricaoCnae: simulada['Descrição do CNAE'], razao: simulada['Razão social'] };
} else if (api.razao_social) {
  receita = { situacao: api.descricao_situacao_cadastral, cnae: String(api.cnae_fiscal || ''), descricaoCnae: api.cnae_fiscal_descricao, razao: api.razao_social };
}
const apiFalhou = !receita && api.error && !JSON.stringify(api.error).includes('404');

// 2. Checagens da Receita
const vermelhos = [];
if (r.cnpj_valido) {
  if (apiFalhou) {
    vermelhos.push('Consulta à Receita indisponível: cadastro enviado para revisão humana');
  } else if (!receita) {
    vermelhos.push('CNPJ não encontrado na Receita');
  } else {
    if (norm(receita.situacao) !== 'ativa') vermelhos.push('CNPJ com situação ' + receita.situacao + ' na Receita');
    const cnae = receita.cnae.replace(/\D/g, '');
    const alimentacao = ['5611','5612','5620','1091','4721'].some(p => cnae.startsWith(p));
    if (!alimentacao) vermelhos.push('Atividade principal não é de alimentação: ' + receita.descricaoCnae);
    if (normRazao(receita.razao) !== normRazao(r.razao_social)) vermelhos.push('Razão social diferente da registrada na Receita (' + receita.razao + ')');
  }
}

// 3. Semáforo das regras cadastrais
let semaforo = 'Verde';
if (vermelhos.length) semaforo = 'Vermelho';
else if (r.pendencias_regras.length) semaforo = 'Amarelo';
const motivos = [...vermelhos, ...r.pendencias_regras];
const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
return { json: {
  'Protocolo': 'ATV-' + r.cnpj,
  'Recebido em': agora,
  'Atualizado em': agora,
  'CNPJ': r.cnpj_formatado,
  'Razão social': r.razao_social,
  'Nome fantasia': r.nome_fantasia,
  'E-mail': r.email,
  'Telefone': r.telefone,
  'Cidade/UF': r.cidade_uf,
  'Cardápio': r.cardapio,
  'Checagens de regras': motivos.length ? motivos.join('\n') : 'OK',
  'Análise da IA': 'pendente',
  'Confiança da IA': '',
  'Semáforo': semaforo,
  'Motivo': motivos[0] || '',
  'ID do envio': r.envio_id,
  'Status': { Verde: 'Aprovado', Amarelo: 'Pendência aberta', Vermelho: 'Em revisão' }[semaforo]
}};

const base = $('Semáforo').item.json;
const respIA = $('Analisar cardápio').item.json;
const anterior = $json['CNPJ'] ? $json : null;
const norm = s => (s || '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const NOMES = {
  descricao_ausente: 'Descrição ausente',
  alergenicos_nao_informados: 'Alergênicos não informados',
  preco_invalido: 'Preço inválido',
  alergenico_nao_declarado: 'Possível alergênico não declarado',
  preco_incoerente: 'Preço fora do padrão',
  item_proibido: 'Item proibido',
  item_fora_do_ramo: 'Item fora do ramo'
};
const AVISOS = ['alergenico_nao_declarado', 'preco_incoerente'];
const ALERGENOS = {
  'glúten': /\btrigo\b|\bmassas?\b|\bpao\b(?! de queijo)|\bpaes\b|\bempanad[oa]s?\b|\bbiscoitos?\b|\bgranola\b|\btortilha\b|\bmacarrao\b|\bbrioche\b/,
  'lactose': /\bleite\b|\bqueijos?\b|\bmanteiga\b|\bcreme\b|\bcream cheese\b|\biogurte\b|\bmucarela\b|\bmussarela\b|\brequeijao\b|\bcheddar\b|\bmascarpone\b/,
  'ovo': /\bovos?\b|\bmerengue\b/,
  'peixe': /\bpeixes?\b|\bsalmao\b|\batum\b|\btilapia\b|\bbacalhau\b/,
  'crustáceos': /\bcamar(ao|oes)\b|\blagostas?\b/,
  'soja': /\bsoja\b|\bshoyu\b|\btofu\b/,
  'amendoim': /\bamendoim\b/,
  'castanhas': /\bcastanhas?\b|\bnozes\b/,
  'gergelim': /\bgergelim\b|\btahine\b/
};

// 1. Regras fixas sobre cada linha do cardápio (sem IA)
const itens = (base['Cardápio'] || '').split('\n').map(l => l.trim()).filter(Boolean).map(l => {
  const [nome = '', descricao = '', preco = '', alergenos = ''] = l.split('|').map(c => c.trim());
  return { nome, descricao, preco, alergenos };
});
const problemas = [];
for (const it of itens) {
  if (!it.descricao) problemas.push({ item: it.nome, tipo: 'descricao_ausente', detalhe: 'inclua uma descrição com os principais ingredientes.' });
  if (!it.alergenos) problemas.push({ item: it.nome, tipo: 'alergenicos_nao_informados', detalhe: 'informe os alergênicos do item ou escreva "nenhum".' });
  const valor = Number(it.preco.replace(/[^\d,]/g, '').replace(',', '.'));
  if (!valor) problemas.push({ item: it.nome, tipo: 'preco_invalido', detalhe: 'informe um preço válido em reais.' });
  if (it.alergenos) {
    const txt = norm(it.nome + ' ' + it.descricao);
    const declarados = norm(it.alergenos);
    for (const [alergeno, regex] of Object.entries(ALERGENOS)) {
      const achado = txt.match(regex);
      if (achado && !declarados.includes(norm(alergeno).slice(0, 6))) {
        const palavra = (it.nome + ' ' + it.descricao).toLowerCase().substr(achado.index, achado[0].length);
        problemas.push({ item: it.nome, tipo: 'alergenico_nao_declarado', detalhe: 'a descrição cita "' + palavra + '", que indica ' + alergeno + ', mas ' + alergeno + ' não está entre os alergênicos declarados.' });
      }
    }
  }
}

// 2. Ler a resposta da IA
const partes = respIA.content?.parts || [];
const textoIA = (partes.find(p => p.text)?.text || '').replace(/```json|```/g, '').trim();
let ia = null;
try { ia = JSON.parse(textoIA); } catch (e) { ia = null; }
const confianca = ia ? (ia.confianca || 'baixa') : 'baixa';

// 3. Aceitar da IA só os tipos que dependem de interpretação
const TIPOS_IA = ['preco_incoerente', 'item_proibido', 'item_fora_do_ramo'];
let descartados = 0;
for (const p of (ia?.problemas || [])) {
  if (!TIPOS_IA.includes(p.tipo)) { descartados++; continue; }
  if (p.tipo === 'preco_incoerente' && problemas.some(q => q.tipo === 'preco_invalido' && norm(q.item) === norm(p.item))) continue;
  problemas.push(p);
}

// 4. Reenvio: o restaurante já foi avisado e manteve o cardápio igual?
const reenvioSemAlteracao = !!anterior && anterior['Status'] === 'Pendência aberta' && norm(anterior['Cardápio']) === norm(base['Cardápio']) && !!anterior['ID do envio'] && anterior['ID do envio'] !== base['ID do envio'];
const avisos = problemas.filter(p => AVISOS.includes(p.tipo));
const obrigatorios = problemas.filter(p => !AVISOS.includes(p.tipo) && !['item_proibido', 'item_fora_do_ramo'].includes(p.tipo));
const avisosAceitos = reenvioSemAlteracao && avisos.length > 0;

// 5. Decidir o semáforo por regra
const tipos = problemas.map(p => p.tipo);
const vermelhosIA = [];
if (!ia) vermelhosIA.push('Falha na análise da IA: cadastro enviado para revisão humana');
if (tipos.includes('item_proibido')) vermelhosIA.push('Item proibido no cardápio');
if (tipos.includes('item_fora_do_ramo')) vermelhosIA.push('Item fora do ramo de alimentação no cardápio');
if (ia && confianca === 'baixa') vermelhosIA.push('Cardápio sem informações suficientes para análise (IA com baixa confiança)');
let semaforo = 'Verde';
if (base['Semáforo'] === 'Vermelho' || vermelhosIA.length) semaforo = 'Vermelho';
else if (base['Semáforo'] === 'Amarelo' || obrigatorios.length || (avisos.length && !avisosAceitos)) semaforo = 'Amarelo';

let status = { Verde: 'Aprovado', Amarelo: 'Pendência aberta', Vermelho: 'Em revisão' }[semaforo];
if (semaforo === 'Verde' && avisosAceitos) status = 'Aprovado com avisos (restaurante ciente)';
else if (semaforo === 'Verde' && anterior && anterior['Status'] === 'Pendência aberta') status = 'Aprovado (pendência resolvida)';

const linhas = problemas.map(p => `${p.item}: ${NOMES[p.tipo]} – ${p.detalhe}`);
let analise = linhas.length ? linhas.join('\n') : (ia ? 'Nenhum problema encontrado' : 'Falha na análise');
if (avisosAceitos) analise += '\n(avisos mantidos pelo restaurante após notificação)';
if (descartados) analise += `\n(${descartados} apontamento(s) da IA fora do escopo descartado(s))`;
const motivo = avisosAceitos && semaforo === 'Verde'
  ? `Restaurante manteve o cardápio após aviso: ${[...new Set(avisos.map(p => NOMES[p.tipo]))].join(', ')}`
  : [base['Semáforo'] === 'Vermelho' ? base['Motivo'] : '', vermelhosIA[0], base['Motivo'], linhas[0]].find(Boolean) || '';

return { json: {
  ...base,
  'Recebido em': anterior?.['Recebido em'] || base['Recebido em'],
  'Análise da IA': analise,
  'Confiança da IA': confianca,
  'Semáforo': semaforo,
  'Motivo': motivo,
  'Status': status,
  '_mensagem_restaurante': problemas.map(p => `• ${AVISOS.includes(p.tipo) ? 'Aviso – ' : ''}${p.item}: ${p.detalhe}`).join('<br>')
}};
